    feedsSort: 'বাছাই এবং ফিল্টারিং:',
    feedsSortDesc: 'সর্বশেষটি সাজানোর ট্যাবে প্রথমে আসে, তারপরে সর্বাধিক টিপস সহ প্রবৃত্তি প্রকারগুলি অনুসরণ করে । একটি হ্যাশট্যাগ ব্যবহার করে এটিতে ফিড ফিল্টার করা, আপনি ইতিমধ্যে যে ভিডিওগুলি দেখেছেন তা চিহ্নিত এবং লুকানো যেতে পারে এবং হোমের শীর্ষে যে কোনও লাইভ স্টেজ বসানো যেতে পারে ।',
    feedsReactionsDesc: 'দশটি প্রতিক্রিয়া লাইক বোতামের পিছনে বসে: যেমন, ভালবাসা, সম্মান, গরম, 100, হাঃ হাঃ, দুঃখী, কান্নাকাটি, পু এবং অপছন্দ । অপছন্দ ব্যতীত প্রত্যেকে পোস্টের মোটের মতো গণনা করে । এটি পছন্দ করতে একটি পোস্টে দুবার ট্যাপ করুন, এটি পছন্দ করতে ট্রিপল-ট্যাপ করুন এবং ট্রেটি খুলতে বোতামটি ধরে রাখুন, যা দেখায় কে প্রতিক্রিয়া জানিয়েছে এবং কী দিয়ে । একটি কার্ডের শীর্ষস্থানীয় আইকনটি হ \'ল পোস্টটিতে যে প্রতিক্রিয়াটি সবচেয়ে বেশি আঁকা হয়েছে । একটি প্রতিক্রিয়া চুল্লির ব্যাজ দ্বারা ওজন করা হয়, তাই কে বিষয়গুলির প্রতিক্রিয়া জানায় এবং কতজন তা করে । সেটিংসে বাম-হাতি মোডটি বারের বাম দিকে লাইক বোতামটি সরিয়ে দেয় ।',
    feedsCommentsDesc: 'প্রতিটি পোস্ট তাদের নিজস্ব পছন্দ, অপছন্দ এবং ভিউ গণনা সহ মন্তব্য বহন করে । এর উত্তর দিতে একটি মন্তব্যে ট্যাপ করুন । যখন কোনও লেখক নিজের কাছে উত্তর দেয় তখন রানটি একটি সংখ্যাসূচক থ্রেড হয়ে যায় । একজন স্রষ্টা তাদের নিজস্ব পোস্টে একটি মন্তব্য পিন করতে পারেন; থ্রেডটি তখন সেই পিনটি নিয়ে যায়, তারপরে একটি প্রদত্ত মন্তব্য অ্যাঙ্কর, তারপরে পাঁচটি সর্বাধিক-টিপ করা মন্তব্য । নির্মাতারা একটি পোস্টের জন্য কমন গ্রাউন্ড মোড চালু করতে পারেন, যা তাদের প্রথম উত্তরের আগে পাঠকদেরকে অন্য পক্ষের সবচেয়ে শক্তিশালী পয়েন্টের জন্য জিজ্ঞাসা করে এবং মন্তব্য বাক্সের এআই বোতামটি আপনার টোনটি পরীক্ষা করে, এর স্টাইল পরিবর্তন করে বা বানান এবং ব্যাকরণ সংশোধন করে । যে কোনও মন্তব্য এর শেয়ার মেনু থেকে রিপোর্ট করা যেতে পারে ।',
    feedsMuteDesc: 'যে কোনও পোস্টে menu মেনু থেকে কোনও লেখককে নিঃশব্দ করুন বা ব্লক করুন । মিউটেশন তাদের নিঃশব্দে আপনার ফিড থেকে ফেলে দেয় এবং পূর্বাবস্থায় ফেরানো যেতে পারে; ব্লকিং আরও এগিয়ে যায়, উভয় উপায়ে কাজ করে এবং মেসেজিংকেও কেটে দেয় ।',
