    communitiesB1Desc: 'কমিউনিটি পেজ থেকে সম্প্রদায়গুলি আবিষ্কার করুন এবং একটি ট্যাপে যোগ দিন । ব্যক্তিগত সম্প্রদায়গুলি যোগদানের অনুরোধ গ্রহণ করে, যা মালিক অনুমোদন করেন এবং নেভিগেশনে একটি অপঠিত ব্যাজ হিসাবে নতুন ক্রিয়াকলাপ দেখায় ।',
