    walletHubB1Desc: 'ETH, BNB, USDT, USDC এবং আরও অনেক কিছু জুড়ে DeHub টোকেন ধারণকারী একটি মাল্টি-চেইন ওয়ালেট, BNB চেইন, ইথেরিয়াম, রবিনহুড চেইন এবং আর্ক, এবং আপনার সোলানা হোল্ডিংস । শূন্য ব্যালেন্স লুকানো আছে এবং কোনও ঠিকানা অনুলিপি করার আগে অ্যাপটি আপনাকে জিজ্ঞাসা করে যে আপনি কোন নেটওয়ার্কটি বোঝাতে চাইছেন । প্রাপ্তি, প্রেরণ, ক্রয়, বাণিজ্য, স্টেক, সেতু এবং ক্যাশ আউট ব্যালেন্স থেকে এক ট্যাপ ।',
