    aiSuiteCreditsDesc: 'প্রজন্ম DeHub টোকেনে পরিশোধ করা হয় । সার্ভারটি চালানোর আগে একটি কাজের মূল্য উদ্ধৃত করে, আপনি একটি স্থানান্তর অনুমোদন করেন এবং চেইনটিতে পেমেন্ট নিশ্চিত হওয়ার পরে কাজটি শুরু হয় । প্রতিটি ওয়ালেটে সর্বনিম্ন মূল্যের মডেলগুলিতে পাঁচটি বিনামূল্যে ছবি থাকে, এবং আপনার সৃষ্টিকর্তা পৃষ্ঠায় ডলার মূল্যের টোকেনের ব্যালেন্স প্রতিবার ওয়ালেট স্বাক্ষর ছাড়াই কাজের জন্য অর্থ প্রদান করতে পারে । পর্যায় ডাবিং প্রতি মিনিটে একইভাবে বিল করা হয় ।',
    adsPortalDesc: 'ব্যবসাগুলি স্ব-পরিষেবা বিজ্ঞাপন পোর্টালের মাধ্যমে DeHub-এ প্রচারাভিযান চালাতে পারে — প্রচারাভিযান তৈরি করুন, DeHub টোকেন দিয়ে টপ-আপ করুন এবং পারফরম্যান্স ট্র্যাক করুন, ফিডে স্থানীয়ভাবে বিজ্ঞাপন পরিবেশন করা হয়েছে । একটি পোস্ট পেজে মন্তব্যগুলি যে কোনও বিজ্ঞাপনের আগে আসে এবং পাঠকরা কম বিজ্ঞাপন দেখতে চাইতে পারেন ।',
    notificationsB1Desc: 'সেটিংসে প্রতি-ক্যাটাগরির পছন্দগুলি ঠিক করে কী পাঠানো হয়, যাতে আপনি বকশিস এবং ড্রপ প্রতিক্রিয়া রাখতে পারেন । ট্যাবগুলি ক্রিয়াকলাপ অনুসারে র ‌ ্যাঙ্ক করা হয়, প্রতিটি নিজস্ব অপঠিত গণনা দেখায় এবং আপনি প্রতি ঘন্টায় কতগুলি পৌঁছান তার একটি সীমা সহ পাবলিক চ্যাট সতর্কতা বেছে নিতে পারেন ।',
    notificationsB6: 'ব্যাজ:',
