    tocPacks: 'ইমোজি এবং প্যাক',
    packsTitle: 'ইমোজি, স্টিকার এবং প্যাক',
    packsDesc: 'ইমোজি পিকারে সার্চ, স্কিন টোন এবং রেকেন্টস সহ প্রতিটি ইমোজি এবং অন্যান্য অ্যাপ থেকে ইমোজি ইনলাইন রেন্ডার করা হয় । সর্বোপরি, ব্যাজ হোল্ডাররা তাদের নিজস্ব ইমোজি, স্টিকার এবং জিআইএফ প্যাক তৈরি করে এবং যে কেউ তাদের পিকারে একটি শেয়ার করা প্যাক যোগ করতে পারেন এবং চ্যাট, মন্তব্য এবং প্রতিক্রিয়াতে এটি ব্যবহার করতে পারেন ।',
    packsB1: 'একটি প্যাক তৈরি করুন:',
    packsB1Desc: 'ইমোজি, স্টিকার বা জিআইএফ প্যাক তৈরি করতে ছবি বা পেস্ট লিঙ্ক আপলোড করুন । উচ্চতর ব্যাজ স্তরগুলি প্রতিটিতে আরও প্যাক এবং আরও বেশি জায়গা পায় ।',
    packsB2: 'এটি শেয়ার করুন:',
    packsB2Desc: 'প্রতিটি প্যাকে শেয়ার করার জন্য একটি লিঙ্ক সহ dehub.io/packs এ নিজস্ব পৃষ্ঠা রয়েছে এবং প্রত্যেকের ব্রাউজ করার জন্য সর্বাধিক যুক্ত প্যাকগুলি তালিকাভুক্ত করা হয়েছে ।',
    tocCinema: 'সিনেমা',
    cinemaTitle: 'সিনেমা',
    cinemaDesc: 'Dehub.io/cinema-তে সিনেমা হল চলচ্চিত্র এবং সিরিজের জন্য যেখানে দেখার জন্য অনুসন্ধান করা হয় । একটি শিরোনাম অনুসন্ধান করুন এবং আপনার দেশে এটি দেখার জন্য প্রতিটি আইনি উপায় দেখুন — কোন পরিষেবাগুলি এটি স্ট্রিম করে, ভাড়া বাবদ কত খরচ হয় এবং এর মালিক হতে কত খরচ হয় । প্রতিটি চলচ্চিত্র এবং সিরিজের একটি শেয়ার কার্ড সহ নিজস্ব পৃষ্ঠা রয়েছে এবং সম্প্রদায় সেখানে এটি পর্যালোচনা করতে পারে ।',
    themesDesc: 'DeHub জাহাজ চৌদ্দটি চেহারা বিকল্প, একটি হালকা ও গাঢ় টগল নয়: সিস্টেম, লাইট, মিনিমাল, কসমিক, হ্যাজি, সোয়ার্মস, লাভা ল্যাম্প, শীতকাল, যুদ্ধ, ওসাকা, জঙ্গল, দ্বীপ, হ্যাকার এবং হরর । প্রতিটি একটি সম্পূর্ণ ত্বক — নিজস্ব প্যালেট, ক্রোম, আইকনোগ্রাফি এবং তাদের অনেকের জন্য, জিপিইউতে রেন্ডার করা একটি লাইভ অ্যানিমেটেড ব্যাকগ্রাউন্ড । আইল্যান্ড একটি লেগুন যা আপনার স্থানীয় ঘড়িকে গোল্ডেন আওয়ার থেকে রাতের দিকে অনুসরণ করে, হ্যাকার মনোস্পেসে সেট করা অ্যাপের সাথে ধীরে ধীরে সবুজ বৃষ্টি হয় এবং হরর একটি জীর্ণ ভিএইচএস টেপে ফুটেজ পাওয়া যায় । সেটিংস অ্যাপিয়ারেন্সে একটি বেছে → নিন, যেখানে প্রতিটি একটি নমুনা দেখায়; এর মধ্যে চারটি আপনাকে আপনার নিজস্ব অ্যাকসেন্টের রঙ সেট করতে দেয় এবং জঙ্গলের নিজস্ব দিন এবং সন্ধ্যা স্যুইচ রয়েছে ।',
    studioB4Desc: 'DeHub টোকেনে প্রতি কাজের জন্য অর্থ প্রদান করুন, এটি চালানোর আগে মূল্য উদ্ধৃত করা হয়েছে । ভারী ব্যবহারকারীরা পরিবর্তে মাসিক টোকেন ভাতার জন্য একটি ক্রিয়েটর, আল্ট্রা, টিম বা স্কেল প্ল্যান নিতে পারেন — পরিকল্পনাগুলি dehub.io/pricing-এ তালিকাভুক্ত করা হয়েছে ।',
    studioB5: 'ক্রিয়েটর ফ্লো এবং প্রিসেট:',
    studioB5Desc: 'Dehub.io/creator/flow চেইনে ক্রিয়েটর ফ্লো প্রম্পট, একটি ক্যানভাসে রেফারেন্স এবং জেনারেটরের পদক্ষেপ এবং পুরো খরচ এক পেমেন্ট হিসাবে । ষোলটি প্রিসেট পণ্য অঙ্কুর, ইউজিসি এবং বিজ্ঞাপন ফর্ম্যাট এবং চিত্রণ শৈলী কভার করে ।',
