    tocMiniApps: 'মিনি অ্যাপস',
    miniAppsTitle: 'মিনি অ্যাপস',
    miniAppsDesc: 'অ্যাপস, মেনুতে এবং dehub.io/apps-এ, যে কেউ DeHub-এর জন্য তৈরি করা মিনি অ্যাপের স্টোর । একটি মিনি অ্যাপ শুধুমাত্র DeHub ড্রয়ের হেডারের অধীনে DeHub-এর ভিতরে খোলে, আপনি ইতিমধ্যে সাইন ইন করেছেন এবং প্রতিটি অ্যাপের আসল ওয়েব ঠিকানা দেখায় ।',
