    miniAppsB3Desc: 'যে কোনও ওয়েবসাইট একটি স্ক্রিপ্ট ট্যাগ সহ একটি মিনি অ্যাপে পরিণত হয় । dehub.io/apps/dev আপনার স্পষ্টতা পরীক্ষা করে, আপনার ফিড কার্ডের পূর্বরূপ দেখে এবং অন্য কেউ এটি দেখার আগে DeHub-এর ভিতরে অ্যাপটি চালায় । Farcaster মিনি অ্যাপস যেভাবে কাজ করে ।',
    miniAppsB4: 'পর্যালোচনা করা তালিকা:',
    miniAppsB4Desc: 'প্রতিটি অ্যাপকে যাচাই করা হয়েছে, রিভিউ করা হয়নি বা ডেভেলপার প্রিভিউ হিসাবে চিহ্নিত করা হয়েছে, তাই আপনি কী খুলছেন তা আপনি জানেন ।',
    arcadeDesc: 'আর্কেড হল একটি ব্রাউজার ট্যাবে DeHub এর ভিতরে চালানো গেমগুলির একটি শেল্ফ । ইনস্টল করার মতো কিছু নেই, কেনার মতো কিছু নেই, আলাদা অ্যাকাউন্ট নেই: একটি খুলুন এবং খেলুন । আজ ছয়টি শিরোনাম জাহাজ — কিংস গ্যাম্বিট, একটি অনলাইন এলো মই সহ একটি সিনেমাটিক 3D দাবা খেলা; ক্লাউড অফ ডিউটি, একটি শ্যুটার যা আপনার মেশিনে প্রতিটি জাল, টেক্সচার এবং শব্দকে লেভেল লোড হিসাবে তৈরি করে; জঙ্গল ট্রেইল, একটি প্রথম ব্যক্তি একটি পদ্ধতিগতভাবে উত্পন্ন রেইনফরেস্ট মাধ্যমে হাঁটা; স্ট্রিট স্লেয়ার, একটি সাইড স্ক্রোলিং বীট \'তাদের আপ নির্মিত deHub-এর জন্য; Chartopia, একটি ট্রেডিং ফ্লোর যা আপনি হাঁটতে পারেন, ডেস্ক মনিটরগুলিতে লাইভ মার্কেট ফিড এবং WebXR-এর মাধ্যমে একটি VR মোড সহ; এবং God\'s Eye, একটি লাইভ 3D গ্লোব যেখানে আপনি DeHub সম্প্রদায়ের মধ্যে নিজের একটি আনুমানিক সংস্করণ স্থাপন করতে বেছে নিতে পারেন । ডেভেলপাররা পর্যালোচনার জন্য তাদের নিজস্ব গেম জমা দিতে পারেন ।',
    settingsB2Desc: 'প্রতিটি থিমের একটি নমুনা, আরামদায়ক বা কমপ্যাক্ট ডেনসিটি, ডিমেড লাইট, থিমের একটি অ্যাকসেন্ট কালার যা এক এবং বাম-হাতি মোড নেয় ।',
    settingsB3Desc: 'পরিপক্ক বিষয়বস্তু আপনার জন্য প্রদর্শিত হবে কিনা, কিডস মোড, ডিফল্ট পোস্ট দৃশ্যমানতা, অটোপ্লে এবং এটি নিঃশব্দে শুরু হবে কিনা এবং মিটারযুক্ত সংযোগগুলির জন্য একটি ডেটা-সার্ভার মোড ।',
    settingsB4Desc: 'সরাসরি মেসেজ অ্যাক্সেস এবং ফি, আপনি যখন অনলাইনে থাকবেন, অবরুদ্ধ অ্যাকাউন্ট, অবরুদ্ধ দেশগুলি, বিরক্ত করবেন না এবং শান্ত সময়গুলি যা আপনার পছন্দসই উইন্ডোর জন্য সবকিছু নীরব করে ।',
    settingsB6Desc: 'আপনার চ্যাটগুলি এক্সপোর্ট করুন, আপনার ডেটা এক্সট্র্যাক্ট করুন, আপনার অ্যাকাউন্টে সাইন ইন করা ডিভাইস এবং সেশনগুলি পর্যালোচনা করুন, AI সিস্টেমগুলি আপনার কাজে প্রশিক্ষণ দিতে পারে কিনা তা বেছে নিন (যদি না আপনি এটি বন্ধ করে দেন) এবং আপনার অ্যাকাউন্ট মুছে ফেলুন ।',
    settingsB7: 'সংযুক্ত অ্যাকাউন্ট এবং সম্পদ:',
