    softwareDevelopers: 'DeHub কারা পরিচালনা করে',
    softwareDevText1: 'DeHub একটি স্বাধীন DAO । কোনও সংস্থা পরিষেবাটির মালিকানা, পরিচালনা বা নিয়ন্ত্রণ করে না । প্রোটোকল, প্ল্যাটফর্ম এবং ট্রেজারি DeHub টোকেন হোল্ডারদের দ্বারা DeHub গভর্নেন্স প্রোটোকলের মাধ্যমে অন-চেইন দ্বারা পরিচালিত হয়, যা লাইভ: প্রস্তাবগুলি অ্যাপে উত্থাপিত এবং ভোট দেওয়া হয় এবং ফলাফলটি বাস্তুতন্ত্রকে আবদ্ধ করে । এই চুক্তিতে "DeHub", "আমরা", "আমাদের" এবং "আমাদের" অর্থ DAO এবং এটি পরিচালিত প্রোটোকল, কোনও সংস্থা নয় ।',
    softwareDevText2: 'উন্নয়নের কাজ করেন DAO-র নিযুক্ত স্বাধীন অবদানকারী ও স্টুডিওগুলি। তাঁদের কেউই DeHub ইকোসিস্টেমের মালিক নন এবং এর উপর সিদ্ধান্ত নেওয়ার ক্ষমতাও রাখেন না, আর যে কাউকে গভর্নেন্স ভোটের মাধ্যমে বদল বা অপসারণ করা যায়। এই প্রক্রিয়ার বাইরে কেউ প্রোটোকল, টোকেন বা এই শর্তাবলি বদলাতে পারে না।',
