    doCollectItem1: 'আপনি যে আইডেন্টিফায়ার দিয়ে সাইন ইন করেছেন — আপনি যদি সেই রুটগুলির মধ্যে একটি বেছে নেন তবে একটি ইমেল ঠিকানা বা ফোন নম্বর, আপনি যদি সামাজিকভাবে সাইন ইন করেন তবে Google, Apple বা Telegram যে পরিচয়টি ফেরত দেয়, বা পাসকির সর্বজনীন পরিচয়পত্র । ওয়ালেট সাইন-ইন আমাদের আপনার সর্বজনীন ঠিকানা ছাড়া আর কিছুই দেয় না ।',
